create table if not exists organizations (id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz default now());
create table if not exists profiles (id uuid primary key, org_id uuid references organizations(id), full_name text, role text default 'Viewer', created_at timestamptz default now());
create table if not exists counterparties (id uuid primary key default gen_random_uuid(), org_id uuid references organizations(id), name text not null, type text, jurisdiction text, risk_level text default 'Low', created_at timestamptz default now());
create table if not exists deals (id uuid primary key default gen_random_uuid(), org_id uuid references organizations(id), deal_code text unique, commodity text, buyer_id uuid references counterparties(id), seller_id uuid references counterparties(id), value numeric, status text, risk_level text, progress int default 0, created_at timestamptz default now());
create table if not exists documents (id uuid primary key default gen_random_uuid(), org_id uuid references organizations(id), deal_id uuid references deals(id), name text, template text, content text, status text default 'Draft', created_at timestamptz default now());
create table if not exists audit_logs (id uuid primary key default gen_random_uuid(), org_id uuid references organizations(id), actor uuid, action text, entity text, created_at timestamptz default now());
